package com.mfg.erp.entity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
/** ERP 生产订单：承接已确认销售需求，随后由 MES 执行。 */
@Entity @Table(name="erp_prod_order",catalog="src_erp") @Getter @Setter @NoArgsConstructor public class ProductionOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="prod_order_no")private String prodOrderNo;@Column(name="sales_order_no")private String salesOrderNo;@Column(name="product_code")private String productCode;@Column(name="product_name")private String productName;@Column(name="plan_qty")private BigDecimal planQty;@Column(name="unit_code")private String unitCode;@Column(name="plan_start_date")private LocalDate planStartDate;@Column(name="plan_finish_date")private LocalDate planFinishDate;@Column(name="order_status")private String status="CREATED";@Column(name="bom_code")private String bomCode;@Column(name="bom_version")private String bomVersion;@Column(name="created_by")private String createdBy;
 @Column(name="production_version_code")private String productionVersionCode;@Column(name="completed_qty")private BigDecimal completedQty=BigDecimal.ZERO;@Column(name="qualified_qty")private BigDecimal qualifiedQty=BigDecimal.ZERO;@Column(name="scrap_qty")private BigDecimal scrapQty=BigDecimal.ZERO;@Column(name="actual_start_date")private LocalDate actualStartDate;@Column(name="actual_finish_date")private LocalDate actualFinishDate;@Column(name="priority_level")private String priorityLevel="NORMAL";@Column(name="factory_code")private String factoryCode;@Column(name="workshop_code")private String workshopCode;@Column(name="cc_code")private String costCenterCode;@Column(name="routing_code")private String routingCode;@Column(name="routing_version")private String routingVersion;@Column(name="kit_status")private String kitStatus="UNCHECKED";@Column(name="kit_checked_at")private LocalDateTime kitCheckedAt;@Column(name="created_at",insertable=false,updatable=false)private LocalDateTime createdAt;@Column(name="updated_at",insertable=false,updatable=false)private LocalDateTime updatedAt;}
